await nats.subscribe(`direct.${modelId}`, async (msg) => {
    // Persist incoming message
    await redis.setMessage(`direct:${msg.id}`, msg);
    if (directMessageHandler) directMessageHandler(msg);
  }, `consumer-${modelId}`);

heartbeatInterval = setInterval(async () => {
    try {
      const existing = await redis.getModelState(modelId);
      await redis.setModelState(modelId, { ...existing, status: 'online', lastHeartbeat: Date.now() });
    } catch (err) {
      console.error(`[comms] Heartbeat failed: ${err.message}`);
    }
  }, 30000);

